using namespace juce;
uint32_t& Studio::noteToolSeedValue(NoteToolMode mode){return mode==NoteToolMode::euclidean?rhythmOptions.seed:mode==NoteToolMode::arpeggiator?arpOptions.seed:noteToolOptions.seed;}
namespace { const double grids[]={4,1,.5,.25,1./6,.125,1./12,.0625}; }
bool Studio::noteToolCurrent()const{return noteToolBound&&noteToolRevision==revision&&noteToolPattern>=0&&noteToolPattern<(int)project.patterns.size()&&noteToolTrack>=0&&noteToolTrack<(int)project.tracks.size()&&project.patterns[(size_t)noteToolPattern].length==noteToolLength&&project.patterns[(size_t)noteToolPattern].lanes[(size_t)noteToolTrack]==noteToolSource;}
bool Studio::pendingNoteTool()const{return noteToolCurrent()&&(!noteToolValid||noteToolCandidate!=noteToolSource);}
const std::vector<Note>& Studio::visibleNotes(int pattern,int track)const{if(noteToolAudition&&noteToolValid&&noteToolCurrent()&&pattern==noteToolPattern&&track==noteToolTrack)return noteToolCandidate;return project.patterns[(size_t)pattern].lanes[(size_t)track];}
void Studio::cancelNoteTool(bool republish){bool restore=noteToolBound&&noteToolAudition;noteToolBound=false;noteToolValid=false;if(restore&&republish)publish();noteToolMessage="Preview cancelled. Project notes are unchanged.";repaint();}
void Studio::openNoteTools(NoteToolMode mode){
    if(recording){status="Finish the take before opening note tools.";return;}if(project.tracks[(size_t)selectedTrack].isBus){status="Choose an instrument channel for note tools.";return;}
    cancelNoteTool(false);noteToolOptions.mode=mode;noteToolPattern=project.activePattern;noteToolTrack=selectedTrack;noteToolLength=project.patterns[(size_t)noteToolPattern].length;noteToolSource=lane();noteToolSelection=selectedNotes;if(noteToolSelection.empty()&&selectedNote>=0&&selectedNote<(int)lane().size())noteToolSelection.insert(selectedNote);
    noteToolCapturedSelection=noteToolSelection;if(mode==NoteToolMode::arpeggiator)pianoLow=-1;
    if(mode==NoteToolMode::euclidean){pianoLow=-1;rhythmOptions.start=0;rhythmOptions.end=noteToolLength;rhythmOptions.pitch=note()?note()->pitch:!noteToolSource.empty()?noteToolSource.front().pitch:project.tracks[(size_t)selectedTrack].instrument<=Instrument::openHat?36:60;noteToolSelection.clear();}
    noteToolTarget=project.patterns[(size_t)noteToolPattern].name+" / "+project.tracks[(size_t)noteToolTrack].name;noteToolRevision=revision;noteToolBound=true;noteToolAudition=true;showPane(pianoPane);showPane(noteToolsPane);refreshNoteToolPreview();
}
void Studio::refreshNoteToolPreview(){
    if(!noteToolCurrent()){cancelNoteTool();noteToolMessage="Source changed. Use current selection to start a new preview.";return;}
    bool rhythm=noteToolOptions.mode==NoteToolMode::euclidean,arp=noteToolOptions.mode==NoteToolMode::arpeggiator;auto result=arp?arpeggiateNotes(noteToolSource,noteToolLength,noteToolSelection,arpOptions,noteToolCandidate,&arpStats):rhythm?generateEuclidean(noteToolSource,noteToolLength,rhythmOptions,noteToolCandidate,&rhythmStats):processNotes(noteToolSource,noteToolLength,noteToolSelection,noteToolOptions,noteToolCandidate);
    noteToolValid=result.wasOk();if(result.failed()){noteToolCandidate=noteToolSource;noteToolMessage=result.getErrorMessage();publish();repaint();return;}
    if(arp)noteToolMessage=String(arpStats.inputNotes)+" source notes / "+String(arpStats.generated)+" arpeggio notes / "+String(arpStats.restSteps)+" rest steps. Apply commits one undo step.";
    else if(rhythm)noteToolMessage=String(rhythmStats.added)+" added / "+String(rhythmStats.removed)+" replaced / "+String(rhythmStats.skipped)+" occupied steps kept. Apply commits one undo step.";
    else{int count=0;for(size_t i=0;i<noteToolSource.size();++i)count+=noteToolSource[i]!=noteToolCandidate[i];noteToolMessage=String(count)+" of "+String((int)(noteToolSelection.empty()?noteToolSource.size():noteToolSelection.size()))+" target notes changed. Apply commits one undo step.";}publish();if(noteToolValid&&(status.startsWith("Preview could not compile:")||status.startsWith("Finish the take")))status="Preview ready. Apply commits one undo step; Cancel restores the original.";repaint();
}
float Studio::noteToolValueFor(int parameter)const{switch(parameter){case 0:return(float)noteToolOptions.positionStrength;case 1:return(float)noteToolOptions.lengthStrength;case 2:return(float)(noteToolOptions.swing*2);case 3:return(float)jlimit(0.,1.,noteToolOptions.window/noteToolOptions.grid);case 4:return(float)(noteToolOptions.timing*4);case 5:return(float)(noteToolOptions.length*4);case 7:return(rhythmOptions.velocity-.01f)/.99f;case 8:return(float)((rhythmOptions.gate-.05)/.95);case 9:return rhythmOptions.variation*2;case 10:return(float)((arpOptions.gate-.05)/.95);case 11:return(arpOptions.velocity-.1f)/1.4f;default:return(float)(noteToolOptions.velocity*2);}}
void Studio::setNoteToolValue(int parameter,float value){
    if(recording)return;value=jlimit(0.f,1.f,value);value=std::round(value*1000)/1000;
    switch(parameter){case 0:noteToolOptions.positionStrength=value;break;case 1:noteToolOptions.lengthStrength=value;break;case 2:noteToolOptions.swing=value*.5;break;case 3:noteToolOptions.window=value*noteToolOptions.grid;break;case 4:noteToolOptions.timing=value*.25;break;case 5:noteToolOptions.length=value*.25;break;case 6:noteToolOptions.velocity=value*.5;break;case 7:rhythmOptions.velocity=.01f+value*.99f;break;case 8:rhythmOptions.gate=.05+value*.95;break;case 9:rhythmOptions.variation=value*.5f;break;case 10:arpOptions.gate=.05+value*.95;break;case 11:arpOptions.velocity=.1f+value*1.4f;break;default:return;}
    if(noteToolCurrent())refreshNoteToolPreview();else repaint();
}
void Studio::noteToolSlider(Graphics& g,const String& name,Rectangle<float> r,int parameter,const String& value){
    label(g,name,r.withWidth(170),12,Colour(0xffd9ddde));Rectangle<float> bar{r.getX()+181,r.getY()+3,r.getWidth()-283,22};g.setColour(Colour(0xff222d32));g.fillRect(bar);g.setColour(Colour(0xff798e70));g.fillRect(bar.withWidth(bar.getWidth()*noteToolValueFor(parameter)));g.setColour(Colour(0xffb8c997));float at=bar.getX()+bar.getWidth()*noteToolValueFor(parameter);g.fillRect(Rectangle<float>{jlimit(bar.getX(),bar.getRight()-3,at-1),bar.getY()+1,3,20});label(g,value,{bar.getRight()+10,r.getY(),92,28},11,Colour(0xffd9ddde));hits.push_back({bar,noteToolValue,parameter});
}
void Studio::paintNoteTools(Graphics& g,Rectangle<float> r){
    Colour text(0xffd9ddde),muted(0xffa5b0b2),accent(0xffb8c997);g.setColour(Colour(0xff394349));g.fillRect(r);float x=r.getX()+14,y=r.getY()+10;bool quant=noteToolOptions.mode==NoteToolMode::quantize,rhythm=noteToolOptions.mode==NoteToolMode::euclidean,arp=noteToolOptions.mode==NoteToolMode::arpeggiator;
    button(g,"Quantize",{x,y,145,27},noteToolMode,0,quant);button(g,"Humanize",{x+153,y,145,27},noteToolMode,1,!quant&&!rhythm&&!arp);button(g,"Euclidean rhythm",{x+306,y,160,27},noteToolMode,2,rhythm);button(g,"Arpeggiator",{x+474,y,145,27},noteToolMode,3,arp);label(g,noteToolCurrent()?noteToolTarget:"No active preview - choose notes, then Use current selection.",{x,y+38,r.getWidth()-28,24},12,text,true);
    button(g,rhythm?"Use current channel":"Use current selection",{x,y+73,173,26},noteToolCapture);button(g,noteToolAudition?"Preview ON":"Original / preview OFF",{x+181,y+73,173,26},noteToolPreview,0,noteToolAudition&&noteToolCurrent());button(g,"Reset settings",{x+362,y+73,122,26},noteToolReset);button(g,"Presets...",{x+492,y+73,127,26},notePresetsOpen);
    if(quant){label(g,"Grid",{x,y+115,70,24},12,text,true);const char* names[]={"Bar","Beat","1/2 beat","1/4 beat","1/6 beat","1/8 beat","1/12 beat","1/16 beat"};for(int i=0;i<8;++i)button(g,names[i],{x+82+(i%4)*112,y+113+(i/4)*32,104,25},noteToolGrid,i,std::abs(noteToolOptions.grid-grids[i])<1e-9);
        noteToolSlider(g,"Position strength",{x,y+187,r.getWidth()-28,28},0,String(noteToolOptions.positionStrength*100,1)+"%");noteToolSlider(g,"Length strength",{x,y+230,r.getWidth()-28,28},1,String(noteToolOptions.lengthStrength*100,1)+"%");noteToolSlider(g,"Grid swing",{x,y+273,r.getWidth()-28,28},2,String(noteToolOptions.swing*100,1)+"%");noteToolSlider(g,"Position window",{x,y+316,r.getWidth()-28,28},3,String(noteToolOptions.window,4)+" beats");
        button(g,"Limit position window",{x,y+357,196,26},noteToolWindow,0,noteToolOptions.useWindow);label(g,"Length strength is independent of the position window.",{x+205,y+357,r.getWidth()-233,26},10,muted);
    }else if(rhythm){paintRhythm(g,r);}else if(arp){paintArpeggiator(g,r);}else{
        noteToolSlider(g,"Timing variation",{x,y+122,r.getWidth()-28,28},4,String(noteToolOptions.timing,4)+" beats");noteToolSlider(g,"Length variation",{x,y+169,r.getWidth()-28,28},5,String(noteToolOptions.length,4)+" beats");noteToolSlider(g,"Velocity variation",{x,y+216,r.getWidth()-28,28},6,String(noteToolOptions.velocity*100,1)+"%");
        button(g,"Keep chord starts together",{x,y+270,229,27},noteToolChords,0,noteToolOptions.keepChords);button(g,"Seed...",{x,y+313,112,26},noteToolSeed);button(g,"New seed",{x+120,y+313,112,26},noteToolReroll);label(g,"Seed: "+String((int64)noteToolOptions.seed),{x+243,y+313,r.getWidth()-271,26},12,text);label(g,"A fixed seed repeats the same variation; only the captured target notes change.",{x,y+359,r.getWidth()-28,24},11,muted);
    }
    Rectangle<float> mini{x,y+405,r.getWidth()-28,68};g.setColour(Colour(0xff253035));g.fillRect(mini);g.saveState();g.reduceClipRegion(mini.toNearestInt());
    if(noteToolCurrent()&&(!noteToolSource.empty()||!noteToolCandidate.empty())){int low=127,high=0;for(const auto& n:noteToolSource){low=jmin(low,n.pitch);high=jmax(high,n.pitch);}for(const auto& n:noteToolCandidate){low=jmin(low,n.pitch);high=jmax(high,n.pitch);}auto paintNotes=[&](const std::vector<Note>& notes,Colour colour,float offset){g.setColour(colour);for(const auto& n:notes){float nx=mini.getX()+(float)(n.beat/noteToolLength)*mini.getWidth(),ny=mini.getBottom()-8-(n.pitch-low)/(float)jmax(1,high-low)*(mini.getHeight()-16)+offset;g.fillRect(Rectangle<float>{nx,ny,jmax(2.f,(float)(n.length/noteToolLength)*mini.getWidth()),2});}};paintNotes(noteToolSource,Colour(0xff849294),-2);if(noteToolAudition&&noteToolValid)paintNotes(noteToolCandidate,accent,2);
    }g.restoreState();label(g,"Original: grey   Preview: green",{x,y+478,r.getWidth()-28,19},10,muted);label(g,noteToolMessage,{x,y+502,r.getWidth()-28,23},11,text);
    label(g,"Apply commits notes for saving/export. Other project edits cancel the preview.",{x,r.getBottom()-76,r.getWidth()-28,22},11,muted);button(g,"Apply",{x,r.getBottom()-42,136,28},noteToolApply,0,false,noteToolCurrent()&&noteToolValid);button(g,"Cancel",{x+144,r.getBottom()-42,136,28},noteToolCancel);
}
bool Studio::performNoteToolAction(int action,int data){
    if(action==notePresetsOpen){if(recording){status="Finish the take before using note presets.";return true;}if(!noteToolCurrent())openNoteTools(noteToolOptions.mode);if(noteToolCurrent())showNotePresets();return true;}
    if(performArpAction(action,data))return true;
    if(performRhythmAction(action,data))return true;
    if(action==quantize||action==humanize){openNoteTools(action==quantize?NoteToolMode::quantize:NoteToolMode::humanize);return true;}
    if(action<quickQuantize||action>noteToolCancel)return false;if(recording){status="Finish the take before editing notes.";return true;}
    if(action==quickQuantize){NoteToolOptions options;options.lengthStrength=1;std::vector<Note> result;auto processed=processNotes(lane(),project.patterns[(size_t)project.activePattern].length,selectedNotes,options,result);if(processed.failed()){status=processed.getErrorMessage();return true;}cancelNoteTool(false);if(result!=lane()){checkpoint();lane()=std::move(result);changed();}else publish();status="Quick quantize: quarter-beat starts and lengths. Ctrl+Z restores the previous notes.";return true;}
    if(action==noteToolCancel){cancelNoteTool();perform(paneClose,noteToolsPane);return true;}
    if(action==noteToolCapture){openNoteTools(noteToolOptions.mode);return true;}
    if(action==noteToolMode){auto previous=noteToolOptions.mode;noteToolOptions.mode=data==3?NoteToolMode::arpeggiator:data==2?NoteToolMode::euclidean:data==1?NoteToolMode::humanize:NoteToolMode::quantize;if(noteToolOptions.mode!=NoteToolMode::euclidean)noteToolSelection=noteToolCapturedSelection;if(noteToolOptions.mode==NoteToolMode::arpeggiator)pianoLow=-1;if(noteToolOptions.mode==NoteToolMode::euclidean&&previous!=NoteToolMode::euclidean){rhythmOptions.start=0;rhythmOptions.end=noteToolLength;if(!noteToolSource.empty()){int index=noteToolSelection.empty()?0:*noteToolSelection.begin();rhythmOptions.pitch=noteToolSource[(size_t)jlimit(0,(int)noteToolSource.size()-1,index)].pitch;}noteToolSelection.clear();}if(!noteToolCurrent())openNoteTools(noteToolOptions.mode);else refreshNoteToolPreview();return true;}
    if(action==noteToolApply){if(!noteToolCurrent()||!noteToolValid){status="Capture a current source and resolve invalid settings before applying.";return true;}bool changedNotes=noteToolCandidate!=noteToolSource;auto notes=noteToolCandidate;int pattern=noteToolPattern,track=noteToolTrack;auto selection=noteToolOptions.mode==NoteToolMode::arpeggiator?std::set<int>{}:noteToolSelection;noteToolBound=false;if(changedNotes){checkpoint();project.patterns[(size_t)pattern].lanes[(size_t)track]=std::move(notes);project.activePattern=pattern;selectedTrack=track;selectedNotes=selection;selectedNote=selection.empty()?-1:*selection.begin();changed();}else publish();panes[noteToolsPane].visible=false;showPane(pianoPane);status=changedNotes?"Note tools applied. One undo restores the original notes.":"No note changes to apply.";return true;}
    if(action==noteToolSeed){auto* dialog=new AlertWindow("Variation seed","Use a whole number from 0 to 4294967295 for repeatable variation.",MessageBoxIconType::NoIcon,this);auto seedMode=noteToolOptions.mode;dialog->addTextEditor("seed",String((int64)noteToolSeedValue(seedMode)));dialog->addButton("Apply",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,seedMode](int r){if(!safe||r!=1||safe->recording)return;auto text=dialog->getTextEditorContents("seed").trim();if(text.isEmpty()||text.length()>10||!text.containsOnly("0123456789"))return;auto seed=text.getLargeIntValue();if(seed<0||seed>4294967295LL)return;safe->noteToolSeedValue(seedMode)=(uint32_t)seed;if(safe->noteToolCurrent())safe->refreshNoteToolPreview();}),true);return true;}
    if(action==noteToolGrid&&data>=0&&data<8){noteToolOptions.grid=grids[data];noteToolOptions.window=noteToolOptions.grid*.5;}
    else if(action==noteToolWindow)noteToolOptions.useWindow=!noteToolOptions.useWindow;
    else if(action==noteToolChords)noteToolOptions.keepChords=!noteToolOptions.keepChords;
    else if(action==noteToolReroll){auto& seed=noteToolSeedValue(noteToolOptions.mode);seed=seed*1664525u+1013904223u;}
    else if(action==noteToolPreview)noteToolAudition=!noteToolAudition;
    else if(action==noteToolReset){auto mode=noteToolOptions.mode;NoteToolOptions defaults;if(mode==NoteToolMode::quantize){noteToolOptions.grid=defaults.grid;noteToolOptions.positionStrength=defaults.positionStrength;noteToolOptions.lengthStrength=defaults.lengthStrength;noteToolOptions.swing=defaults.swing;noteToolOptions.window=defaults.window;noteToolOptions.useWindow=defaults.useWindow;}else if(mode==NoteToolMode::humanize){noteToolOptions.timing=defaults.timing;noteToolOptions.length=defaults.length;noteToolOptions.velocity=defaults.velocity;noteToolOptions.keepChords=defaults.keepChords;noteToolOptions.seed=defaults.seed;}else if(mode==NoteToolMode::euclidean){int pitch=rhythmOptions.pitch;rhythmOptions={};rhythmOptions.pitch=pitch;rhythmOptions.end=noteToolLength;}else arpOptions={};selectedNotePreset[(size_t)mode].clear();}
    if(noteToolCurrent())refreshNoteToolPreview();else repaint();return true;
}
